"use client";
import { useState } from "react";
type Student={id:string;name:string;admissionNo:string};
export default function AttendanceForm({students}:{students:Student[]}) {
  const [msg,setMsg]=useState("");
  async function submit(e:React.FormEvent<HTMLFormElement>){
    e.preventDefault();
    const data=Object.fromEntries(new FormData(e.currentTarget));
    const res=await fetch("/api/attendance",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(data)});
    setMsg(res.ok?"Attendance saved.":"Could not save attendance.");
  }
  return <div className="card"><h2>Mark Attendance</h2><form onSubmit={submit} className="grid grid-2">
    <div><label className="label">Student</label><select className="select" name="studentId" required>{students.map(s=><option key={s.id} value={s.id}>{s.admissionNo} — {s.name}</option>)}</select></div>
    <div><label className="label">Date</label><input className="input" name="date" type="date" required/></div>
    <div><label className="label">Subject</label><input className="input" name="subject" required placeholder="Database Management"/></div>
    <div><label className="label">Status</label><select className="select" name="status"><option>PRESENT</option><option>ABSENT</option><option>LATE</option></select></div>
    <div><button className="btn btn-primary">Save Attendance</button></div>
  </form>{msg&&<p className="muted">{msg}</p>}</div>
}
